    const other = await (await send('/api/projects', 'POST', { name: 'Other' })).json();
    const path = `/api/projects/${project.id}`;
    const tasksPath = `${path}/tasks`;
    const first = await (await send(tasksPath, 'POST', { title: 'Original' })).json();
